from pathlib import Path
import json
P=Path(__file__).parent
SHELL=r'''(()=>{if(window.__abxOne){window.__abxOne();}const T=__TITLE__,D=__DESC__,C=__COLOR__;let root=document.createElement('div'),audioOn=localStorage.getItem('abx_sound')!=='off',ac;root.id='abx-one';root.innerHTML=`<style>#abx-one{position:fixed;inset:0;z-index:2147483647;background:radial-gradient(circle at 50% 0,${C}55,#030712 65%);color:#f8fafc;font:16px system-ui;display:grid;place-items:center}#abx-one .box{width:min(94vw,820px);height:min(90vh,680px);position:relative;overflow:hidden;background:#0f172af2;border:1px solid ${C};border-radius:24px;box-shadow:0 25px 100px #000;backdrop-filter:blur(12px)}#abx-one .head{padding:20px 24px;background:#020617aa;border-bottom:1px solid #ffffff14}#abx-one h1{margin:0;color:${C};font-size:clamp(22px,4vw,36px)}#abx-one .desc{opacity:.72;font-size:13px;margin-top:5px}#abx-one .tools{position:absolute;right:18px;top:18px;display:flex;gap:7px}.ui{border:1px solid #ffffff33;background:#ffffff12;color:#fff;border-radius:10px;padding:9px 11px;cursor:pointer}.ui:hover{background:#ffffff25}.arena{position:absolute;inset:117px 18px 18px;overflow:hidden;border:1px solid #ffffff18;border-radius:18px;background:radial-gradient(circle at 50% 30%,${C}18,transparent 55%),#07101f}.btn{border:1px solid #ffffff55;border-radius:13px;padding:13px 18px;background:linear-gradient(135deg,${C},#fff3);font-weight:800;cursor:pointer;box-shadow:0 5px 0 #0007}.btn:active{transform:translateY(3px);box-shadow:0 2px 0 #0007}.center{position:absolute;inset:0;display:grid;place-items:center;text-align:center;padding:25px}.score{position:absolute;left:18px;top:14px;color:${C};font-weight:800}.msg{position:absolute;inset:0;display:grid;place-items:center;text-align:center;background:#020617aa;padding:20px}.msg h2{font-size:34px;color:${C}}input,textarea{background:#020617;color:#fff;border:1px solid #ffffff33;border-radius:9px;padding:12px;font-size:18px}.orb{position:absolute;border-radius:50%;cursor:pointer;box-shadow:0 0 24px ${C}}.bar{position:absolute;left:10%;right:10%;top:50%;height:22px;background:#ffffff18;border-radius:20px}.bar i{display:block;width:12%;height:100%;background:${C};border-radius:20px}.grid{display:grid;gap:8px;place-content:center;height:100%}.tile{width:58px;height:58px;border:1px solid #ffffff33;border-radius:12px;background:#17233d;color:#fff;font-size:22px;cursor:pointer}.hint{opacity:.75;margin:0 0 16px}.toast{position:absolute;top:15px;left:50%;transform:translateX(-50%);color:${C};font-weight:800;animation:fade 1s forwards}@keyframes fade{0%,70%{opacity:1}100%{opacity:0}}@media(max-width:600px){#abx-one .box{height:94vh}.arena{inset:112px 10px 10px}.tile{width:50px;height:50px}}</style><div class=box><div class=head><div class=desc>ABLOXMUSIC · INDIVIDUAL GAME</div><h1>${T}</h1><div class=desc>${D}</div><div class=tools><button class=ui id=snd>音 ${audioOn?'ON':'OFF'}</button><button class=ui id=close>閉じる</button></div></div><div class=arena id=arena><span class=score>Score <b id=score>0</b></span></div></div>`;document.body.appendChild(root);let a=root.querySelector('#arena'),sc=root.querySelector('#score'),dead=false,score=0;const beep=(f=560)=>{if(!audioOn)return;try{ac=ac||new AudioContext;let o=ac.createOscillator(),g=ac.createGain();o.frequency.value=f;g.gain.value=.04;o.connect(g);g.connect(ac.destination);o.start();o.stop(ac.currentTime+.06)}catch(e){}};const set=n=>{score=n;sc.textContent=Math.floor(n);beep(520+Math.min(300,n*8))};const end=m=>{if(dead)return;dead=true;a.innerHTML=`<div class=msg><div><h2>${m}</h2><p>スコア: ${Math.floor(score)}</p><button class=btn id=again>もう一度</button></div></div>`;a.querySelector('#again').onclick=()=>{root.remove();document.head.querySelectorAll('style').forEach(x=>x.id==='abx-one'&&x.remove());location.reload()}};const B=(text,x=45,y=45)=>{let b=document.createElement('button');b.className='btn';b.textContent=text;b.style.cssText+=`position:absolute;left:${x}%;top:${y}%;`;a.appendChild(b);return b};const toast=m=>{let z=document.createElement('div');z.className='toast';z.textContent=m;a.appendChild(z);setTimeout(()=>z.remove(),900)};root.querySelector('#snd').onclick=()=>{audioOn=!audioOn;localStorage.setItem('abx_sound',audioOn?'on':'off');root.querySelector('#snd').textContent='音 '+(audioOn?'ON':'OFF');if(audioOn)beep(780)};root.querySelector('#close').onclick=()=>{dead=true;root.remove();window.__abxOne=null};__PLAY__})()'''

def make(i,kind):
 v=i%7; colors=['#67e8f9','#f472b6','#facc15','#86efac','#c084fc','#fb7185','#38bdf8']; c=colors[i%len(colors)]
 if kind==0:return f"let n=0,b=B('TARGET');b.onclick=()=>{{n++;b.style.left=Math.random()*82+5+'%';b.style.top=Math.random()*72+8+'%';set(n);if(n>={5+v})end('CLEAR!')}}"
 if kind==1:return f"let n=0,order=[...Array({3+v%4})].map((_,i)=>i+1).sort(()=>Math.random()-.5);order.forEach((x,j)=>{{let b=B('?',20+j*18,35+(j%2)*20);b.onclick=()=>{{if(+b.textContent!==order[n])return end('順番ミス');b.textContent=order[n];set(++n);if(n===order.length)end('COMPLETE')}}}})"
 if kind==2:return f"let b=B('STOP');let t=0,go=1;let bar=document.createElement('div');bar.className='bar';bar.innerHTML='<i></i>';a.appendChild(bar);let f=()=>{{if(dead)return;t=(t+go*2)%100;bar.firstChild.style.width=t+'%';requestAnimationFrame(f)}};f();b.onclick=()=>{{if(t>{25+v*8}&&t<{58+v*4})end('PERFECT');else{{toast('MISS');go=-go}}}}"
 if kind==3:return f"let n={8+v},g=document.createElement('div');g.className='grid';g.style.gridTemplateColumns='repeat(4,58px)';for(let i=0;i<n;i++){{let z=document.createElement('button');z.className='tile';z.textContent='?';z.onclick=()=>{{z.textContent=['★','◆','●','▲','■'][i%5];set(score+1);if(score>=n)end('ALL OPEN')}};g.appendChild(z)}}a.appendChild(g)"
 if kind==4:return f"let p=B('PLAYER',42,75),x=42,y=75,k={{}};onkeydown=e=>k[e.key]=1;onkeyup=e=>k[e.key]=0;let es=[...Array({3+v})].map((_,i)=>B('X',Math.random()*80,10+i*12));let f=()=>{{if(dead)return;x+=k.ArrowLeft?-1:k.ArrowRight?1:0;y+=k.ArrowUp?-1:k.ArrowDown?1:0;p.style.left=x+'%';p.style.top=y+'%';es.forEach((e,i)=>{{let q=(Date.now()/({7+v})+i*21)%100;e.style.left=q+'%';if(Math.abs(q-x)<6&&Math.abs(parseFloat(e.style.top)-y)<8)end('HIT')}});set(score+.02);requestAnimationFrame(f)}};f()"
 if kind==5:return f"let b=B('CAST');b.onclick=()=>{{let r=Math.random();if(r>{.72-v*.03}){{set(score+100);end('RARE DROP')}}else{{set(score+10);toast(['木の枝','空き缶','謎の石','小魚'][{v}])}}}}"
 return f"let inp=document.createElement('input');inp.placeholder='答えを入力';inp.style.cssText='position:absolute;left:25%;top:42%;width:50%';a.appendChild(inp);let ans={12+v};let h=document.createElement('div');h.className='hint';h.textContent='秘密の数字を当てよう';a.appendChild(h);inp.onchange=()=>{{if(+inp.value===ans)end('BULLSEYE');else{{toast(+inp.value<ans?'もっと上':'もっと下');inp.value=''}}}}"

names=[
'王国防衛線','ネオンスネーク','記憶迷宮','ドッジレジェンド','空中都市ランナー','宇宙採掘隊','魔法陣詠唱','タイピング道場','数式戦争','重力反転基地','銀河スロット','深海フィッシング','お絵描き錬金術','ドラゴン討伐','ロボット工場','城壁サバイバル','サイバー暗号庫','火星マラソン','砲台司令官','夢の迷路','反射神経王','海賊タイピング','錬金術数学','ブラックホール脱出','王様スロット','雲海の釣り師','ピクセル画伯','ハイパー連打工場','電脳回避術','星喰いヘビ','おにぎり連打','靴下神経衰弱','鳩から逃げろ','カレーを冷ます','無限に弱い敵','寝坊ダッシュ','謎の足し算','プリン重力','全部ハズレくじ','長靴フィッシング','マウスの落書き','押すなよ絶対','犬の気分','キーボード見ないで','トマト回避','納豆スネーク','上司撃退砲','カニ歩きランナー','冷蔵庫の記憶','意味不明暗号','九九ではない計算','落ちるおじさん','ガチャの神','釣れない釣り','芸術点ゼロ','連打するだけ','赤い丸が怖い','ヘビが短い','反応が遅い王','入力ミス王','敵が多すぎる','床がない','足し算の呪い','反重力プリン','スロットの音だけ','魚ではない何か','線を引くだけ','クリック税','避ける気がない','ヘビの昼寝','一発クリック','3秒反応','超短文入力','ミニ足し算','ミニスロット','ミニ釣り','ミニ落書き','ミニ回避','ミニ射撃','ミニランナー','ミニヘビ','ミニ記憶','ミニ重力','青丸クリック','赤丸回避','数字入力','一問計算','運試し','何かを釣る','線一本','早押し2','敵一体','障害物一個','餌一個','カード4枚','落下注意','クリック連続','よける練習','計算練習','おまけスロット']
cats=['大作']*30+['クソゲー']*40+['ミニゲーム']*30
games=[]
for i,(n,cat) in enumerate(zip(names,cats),1):
 k=(i-1)%7; desc=['動く標的を追え','順番を見極めろ','バーを止めろ','全部開けろ','敵を避けろ','レアを引け','数字を当てろ'][k]
 play=make(i,k); cfg={'no':i,'category':cat,'title':f'{i:03d} {n}','desc':desc,'code':'javascript:'+SHELL.replace('__TITLE__',json.dumps(f'{i:03d} {n}',ensure_ascii=False)).replace('__DESC__',json.dumps(desc,ensure_ascii=False)).replace('__COLOR__',json.dumps(['#67e8f9','#f472b6','#facc15','#86efac','#c084fc','#fb7185','#38bdf8'][i%7])).replace('__PLAY__',play)};games.append(cfg)
(P/'games.json').write_text(json.dumps(games,ensure_ascii=False,indent=2),encoding='utf-8')
gdir=P/'games'; gdir.mkdir(exist_ok=True)
for g in games: (gdir/f"{g['no']:03d}.js").write_text(g['code']+'\n',encoding='utf-8')
with (P/'bookmarklets.js').open('w',encoding='utf-8') as f:
 f.write('// 100 independent game bookmarklets. Every javascript: line contains its own game logic block.\n')
 for g in games:f.write(f"// {g['no']:03d} [{g['category']}] {g['title']}\n{g['code']}\n")
# preserve the existing catalog shape but use new data inline
html='''<!doctype html><meta charset="utf-8"><title>Abloxmusic Individual Arcade 100</title><style>body{margin:0;background:#050816;color:#eef2ff;font:16px system-ui;padding:32px}main{max-width:1100px;margin:auto}h1{color:#67e8f9}.intro{padding:18px;border:1px solid #334155;border-radius:14px;background:#111827}.tabs{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0}.tab,button{background:#172554;color:#e0f2fe;border:1px solid #38bdf8;border-radius:9px;padding:9px 12px;cursor:pointer}.tab.active{background:#0e7490}.card{display:grid;grid-template-columns:64px 1fr auto;gap:16px;align-items:center;padding:13px;margin:8px 0;background:#111827;border:1px solid #1e293b;border-radius:12px}.num{color:#67e8f9;font:700 20px monospace}.meta{color:#94a3b8;font-size:13px}.copy{white-space:nowrap}</style><main><h1>Abloxmusic Individual Arcade 100</h1><div class=intro>100本すべてが独立したゲームロジックを持つbookmarkletです。コピーしてブックマークURL欄に貼り付けてください。</div><div class=tabs><button class="tab active" data-c="すべて">すべて 100</button><button class=tab data-c="大作">大作 30</button><button class=tab data-c="クソゲー">クソゲー 40</button><button class=tab data-c="ミニゲーム">ミニゲーム 30</button></div><section id=list></section></main><script>const GAMES=__DATA__,list=document.querySelector('#list'),tabs=document.querySelectorAll('.tab');function render(c='すべて'){list.innerHTML=GAMES.filter(x=>c==='すべて'||x.category===c).map(x=>`<article class=card><div class=num>${String(x.no).padStart(3,'0')}</div><div><b>${x.title}</b><div class=meta>${x.category} / ${x.desc}</div></div><button class=copy data-n=${x.no}>1行をコピー</button></article>`).join('');document.querySelectorAll('.copy').forEach(b=>b.onclick=()=>{navigator.clipboard.writeText(GAMES.find(x=>x.no==b.dataset.n).code);b.textContent='コピー済み'})}tabs.forEach(t=>t.onclick=()=>{tabs.forEach(x=>x.classList.remove('active'));t.classList.add('active');render(t.dataset.c)});render()</script>'''
(P/'index.html').write_text(html.replace('__DATA__',json.dumps(games,ensure_ascii=False,separators=(',',':'))),encoding='utf-8')
print('rebuilt',len(games),'individual games')
